import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  Button,
  SearchTextInput,
  Slideout,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { bankStatementImportService } from '../../../services/kt/bankStatementImportService';
import {
  BANK_STATEMENT_REPORT_EMPTY_CODE,
  type BankStatementImportReportLine,
} from '../../../services/kt/bankStatementImportModels';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatMoney } from '../../../utils/formatters';
import { extractBankTxnCode, importSaoKeFocusPath } from '../../../utils/extractBankTxnCode';
import { openSourceDocumentView } from '../../../utils/openSourceDocumentView';
import { openWorkspaceTab } from '../../../utils/openWorkspaceTab';
import { titleFromPath } from '../../../workspace/workspaceTabTypes';
import {
  DEFAULT_PAGE_SIZE,
  VoucherListPagination,
  type ListPageSize,
} from '../../../components/list/VoucherListPagination';
import erp from '../../../styles/erpPage.module.css';
import styles from './BaoCaoImportSaoKePage.module.css';

export type UnitDetailTarget = {
  companyCode: string;
  costCode: string;
  lineCount: number;
  totalDebit: number;
  totalCredit: number;
  totalAmount: number;
};

export type BaoCaoImportSaoKeUnitDetailSlideoutProps = {
  isOpen: boolean;
  onClose: () => void;
  target: UnitDetailTarget | null;
  fromDate?: string;
  toDate?: string;
  search?: string;
  testIdPrefix: string;
};

function toFilterCode(value: string | null | undefined): string {
  const t = (value || '').trim();
  return t || BANK_STATEMENT_REPORT_EMPTY_CODE;
}

function displayCode(value: string | null | undefined): string {
  const t = (value || '').trim();
  return t || '(trống)';
}

export const BaoCaoImportSaoKeUnitDetailSlideout: React.FC<
  BaoCaoImportSaoKeUnitDetailSlideoutProps
> = ({ isOpen, onClose, target, fromDate, toDate, testIdPrefix }) => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<ListPageSize>(DEFAULT_PAGE_SIZE);
  const [items, setItems] = useState<BankStatementImportReportLine[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [searchDraft, setSearchDraft] = useState('');
  const [lineSearch, setLineSearch] = useState('');
  const fetchSeq = useRef(0);
  const searchTimer = useRef<number | undefined>(undefined);

  const companyFilter = target ? toFilterCode(target.companyCode) : '';
  const costFilter = target ? toFilterCode(target.costCode) : '';

  const load = useCallback(
    async (targetPage: number, size: number, searchTerm = lineSearch) => {
      if (!isOpen || !target || !fromDate || !toDate) return;
      const seq = ++fetchSeq.current;
      setLoading(true);
      try {
        const data = await bankStatementImportService.getImportReport({
          fromDate,
          toDate,
          companyCode: companyFilter,
          costCode: costFilter,
          search: searchTerm.trim() || undefined,
          page: targetPage,
          pageSize: size,
        });
        if (seq !== fetchSeq.current) return;
        setItems(data.items ?? []);
        setTotalCount(data.totalCount ?? 0);
        setPage(data.page ?? targetPage);
      } catch (err) {
        if (seq !== fetchSeq.current) return;
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được chi tiết đơn vị × mã CP'),
          type: 'error',
        });
      } finally {
        if (seq === fetchSeq.current) setLoading(false);
      }
    },
    [companyFilter, costFilter, dispatch, fromDate, isOpen, lineSearch, target, toDate],
  );

  useEffect(() => {
    if (!isOpen || !target) {
      setItems([]);
      setTotalCount(0);
      setPage(1);
      return;
    }
    setPage(1);
    setSearchDraft('');
    setLineSearch('');
    void load(1, pageSize, '');
  }, [isOpen, target, fromDate, toDate, companyFilter, costFilter]); // eslint-disable-line react-hooks/exhaustive-deps -- reset page on target/period change

  useEffect(() => () => {
    if (searchTimer.current != null) window.clearTimeout(searchTimer.current);
  }, []);

  const applyLineSearch = useCallback((raw: string) => {
    const next = raw.trim();
    setLineSearch(next);
    setPage(1);
    void load(1, pageSize, next);
  }, [load, pageSize]);

  const handleSearchChange = (value: string) => {
    setSearchDraft(value);
    if (searchTimer.current != null) window.clearTimeout(searchTimer.current);
    searchTimer.current = window.setTimeout(() => {
      applyLineSearch(value);
    }, 300);
  };

  const openCreatedVoucher = useCallback(
    (row: BankStatementImportReportLine) => {
      const viewUrl = (row.createdVoucherViewUrl || '').trim();
      const code = (row.createdVoucherCode || '').trim();
      if (!viewUrl) {
        dispatchAppToast(dispatch, {
          type: 'info',
          message: code
            ? `CT «${code}» chưa có link mở — kiểm tra lại sau khi tạo từ IMP`
            : 'Dòng này chưa tạo chứng từ gốc (BC/BN/UNC/CTNB)',
        });
        return;
      }
      const label = titleFromPath(viewUrl);
      openSourceDocumentView({
        sourceDocumentViewUrl: viewUrl,
        title: code ? `${label} — ${code}` : `${label}…`,
        returnPath: `${location.pathname}${location.search}`,
        returnTitle: 'Báo cáo phiếu import sao kê',
        documentType: row.createdVoucherKind ?? undefined,
        navigate,
      });
    },
    [dispatch, location.pathname, location.search, navigate],
  );

  const openImportAtTxn = useCallback(
    (row: BankStatementImportReportLine, e: React.MouseEvent) => {
      if (e.metaKey || e.ctrlKey || e.shiftKey || e.button === 1) return;
      e.preventDefault();
      const gd = (row.referenceCode || extractBankTxnCode(row.description, row.referenceCode) || '').trim();
      if (!gd || !row.importId) return;
      openWorkspaceTab({
        path: importSaoKeFocusPath(row.importId, gd),
        title: row.importCode ? `${row.importCode} · ${gd}` : gd,
        returnPath: `${location.pathname}${location.search}`,
        returnTitle: 'Báo cáo phiếu import sao kê',
      }, navigate);
    },
    [location.pathname, location.search, navigate],
  );

  const title = target
    ? `Chi tiết · ${displayCode(target.companyCode)} × ${displayCode(target.costCode)}`
    : 'Chi tiết đơn vị × mã CP';

  const footer = (
    <div className={styles.slideoutFooter}>
      {totalCount > 0 ? (
        <VoucherListPagination
          testIdPrefix={`${testIdPrefix}-unit-detail`}
          page={page}
          totalCount={totalCount}
          pageSize={pageSize}
          onPageChange={(p) => {
            setPage(p);
            void load(p, pageSize);
          }}
          onPageSizeChange={(ps) => {
            const next = ps as ListPageSize;
            setPageSize(next);
            setPage(1);
            void load(1, next);
          }}
        />
      ) : (
        <span />
      )}
      <Button
        variant="secondary"
        onClick={onClose}
        data-testid={`${testIdPrefix}-unit-detail-close`}
      >
        Đóng
      </Button>
    </div>
  );

  return (
    <Slideout
      isOpen={isOpen}
      onClose={onClose}
      title={title}
      width="min(1100px, 96vw)"
      customFooter={footer}
      data-testid={`${testIdPrefix}-unit-detail-slideout`}
    >
      {target ? (
        <div className={styles.slideoutBody} data-testid={`${testIdPrefix}-unit-detail-body`}>
          <div className={styles.slideoutSummary}>
            <span>
              <strong>{target.lineCount}</strong> dòng trên báo cáo · Chi{' '}
              <strong>{formatMoney(target.totalDebit)}</strong> · Thu{' '}
              <strong>{formatMoney(target.totalCredit)}</strong> · Tổng{' '}
              <strong>{formatMoney(target.totalAmount)}</strong>
            </span>
            {loading ? <span className={styles.muted}>Đang tải…</span> : null}
          </div>
          <div className={styles.slideoutSearch} data-testid={`${testIdPrefix}-unit-detail-search`}>
            <SearchTextInput
              label="Mã GD / nội dung CK"
              value={searchDraft}
              onChange={handleSearchChange}
              onSearch={() => applyLineSearch(searchDraft)}
              placeholder="Nhập mã giao dịch hoặc nội dung chuyển khoản"
              testId={`${testIdPrefix}-unit-detail-filter-search`}
            />
            {lineSearch ? (
              <span className={styles.slideoutSearchMeta} data-testid={`${testIdPrefix}-unit-detail-search-count`}>
                {loading ? 'Đang lọc…' : `${totalCount.toLocaleString('vi-VN')} dòng khớp`}
              </span>
            ) : null}
          </div>
          <div className={`${erp.tableWrapper} ${styles.slideoutTableWrap}`}>
            <table className={erp.table}>
              <thead>
                <tr>
                  <th>STT</th>
                  <th>Ngày chứng từ</th>
                  <th>Số IMP</th>
                  <th>Tiêu đề</th>
                  <th>Mã GD</th>
                  <th>CT gốc</th>
                  <th>Đơn vị</th>
                  <th>Mã CP</th>
                  <th className={`${erp.colAmount} ${styles.num}`}>Chi</th>
                  <th className={`${erp.colAmount} ${styles.num}`}>Thu</th>
                  <th>Đối tượng</th>
                  <th className={styles.descLong}>Diễn giải</th>
                  <th>Nguồn sao kê</th>
                </tr>
              </thead>
              <tbody>
                {items.length === 0 ? (
                  <tr>
                    <td colSpan={13} className={styles.emptyCell}>
                      {loading
                        ? 'Đang tải…'
                        : lineSearch
                          ? `Không có dòng khớp «${lineSearch}».`
                          : 'Không có dòng chi tiết cho nhóm này.'}
                    </td>
                  </tr>
                ) : (
                  items.map((row, idx) => {
                    const gd = (row.referenceCode || extractBankTxnCode(row.description, row.referenceCode) || '').trim();
                    return (
                    <tr key={row.lineId}>
                      <td>{(page - 1) * pageSize + idx + 1}</td>
                      <td>{row.transactionDate || '—'}</td>
                      <td>
                        <a
                          href={`/kt/import-sao-ke/${row.importId}`}
                          data-testid={`${testIdPrefix}-unit-detail-imp-${row.importCode}`}
                        >
                          {row.importCode}
                        </a>
                      </td>
                      <td className={styles.desc} title={row.importTitle || undefined}>
                        {row.importTitle || '—'}
                      </td>
                      <td className={styles.txnCode}>
                        {gd ? (
                          <a
                            href={importSaoKeFocusPath(row.importId, gd)}
                            className={styles.linkBtn}
                            data-testid={`${testIdPrefix}-unit-detail-gd-${row.lineId}`}
                            title="Mở phiếu import tại giao dịch này"
                            onClick={e => openImportAtTxn(row, e)}
                          >
                            {gd}
                          </a>
                        ) : '—'}
                      </td>
                      <td>
                        {row.createdVoucherCode && row.createdVoucherViewUrl ? (
                          <button
                            type="button"
                            className={styles.linkBtn}
                            data-testid={`${testIdPrefix}-unit-detail-src-${row.lineId}`}
                            title="Mở chứng từ gốc để đối soát"
                            onClick={() => openCreatedVoucher(row)}
                          >
                            {row.createdVoucherCode}
                          </button>
                        ) : (
                          <span className={styles.muted}>—</span>
                        )}
                      </td>
                      <td>{row.companyCode || '—'}</td>
                      <td>{row.costCode || '—'}</td>
                      <td className={`${erp.colAmount} ${styles.num}`}>
                        {formatMoney(row.debitAmount)}
                      </td>
                      <td className={`${erp.colAmount} ${styles.num}`}>
                        {formatMoney(row.creditAmount)}
                      </td>
                      <td>{row.customerCode || row.customerName || '—'}</td>
                      <td className={styles.descLong} title={row.description || undefined}>
                        {row.description || '—'}
                      </td>
                      <td className={styles.ref} title={row.importReference || undefined}>
                        {row.importReference || '—'}
                      </td>
                    </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
          {!loading && !lineSearch && totalCount > 0 && totalCount !== target.lineCount ? (
            <p className={styles.slideoutHint} data-testid={`${testIdPrefix}-unit-detail-count-hint`}>
              API trả {totalCount} dòng (tóm tắt báo cáo: {target.lineCount}) — kiểm tra lại bộ lọc kỳ.
            </p>
          ) : null}
        </div>
      ) : null}
    </Slideout>
  );
};

export default BaoCaoImportSaoKeUnitDetailSlideout;
