/**
 * Mã GD sao kê — cột riêng trên báo cáo / phiếu IMP.
 * Ưu tiên ReferenceCode; fallback parse diễn giải (MB Trace / Ma GD / FT).
 */
const TXN_IN_DESC = /(?:m[aã]\s*giao\s*d[iị]ch|m[aã]\s*gd)\s*[/:]?\s*(?:trace\s*)?[/:]?\s*([A-Z0-9][A-Z0-9/\- ]{2,40})/i;
const TRACE_ONLY = /\btrace\s*[/:]?\s*([A-Z0-9]{4,})/i;
const FT_CODE = /\bFT\d{8,20}\b/i;

function tidy(raw: string): string {
  return raw.replace(/\s+/g, ' ').trim().replace(/[.,;]+$/, '');
}

export function extractBankTxnCode(
  description?: string | null,
  referenceCode?: string | null,
): string {
  const stored = (referenceCode || '').trim();
  if (stored) return stored;

  const desc = (description || '').trim();
  if (!desc) return '';

  const fromLabel = desc.match(TXN_IN_DESC)?.[1];
  if (fromLabel) return tidy(fromLabel);

  const fromTrace = desc.match(TRACE_ONLY)?.[1];
  if (fromTrace) return tidy(fromTrace);

  const fromFt = desc.match(FT_CODE)?.[0];
  return fromFt ? tidy(fromFt) : '';
}

export function normBankTxnCode(value?: string | null): string {
  return (value || '').replace(/\s+/g, '').toUpperCase();
}

export function statementMatchesTxnCode(
  line: { description?: string | null; referenceCode?: string | null },
  gd?: string | null,
): boolean {
  const want = normBankTxnCode(gd);
  if (!want) return false;
  const extracted = normBankTxnCode(extractBankTxnCode(line.description, line.referenceCode));
  if (extracted && extracted === want) return true;
  if (normBankTxnCode(line.referenceCode) === want) return true;
  return normBankTxnCode(line.description).includes(want);
}

export function importSaoKeFocusPath(importId: string, txnCode: string): string {
  return `/kt/import-sao-ke/${importId}?gd=${encodeURIComponent(txnCode.trim())}`;
}
