import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  LinErpListFilterBar,
  LinPageLayout,
  LinReportPeriodSelectorFields,
  LIN_ERP_LIST_FILTER_LAYOUT,
  SearchInput,
  SearchTextInput,
  computeReportPeriodDates,
  dispatchAppToast,
  nowMonth,
  nowQuarter,
  nowYear,
  useServerPagedListLoading,
  yearOptionsFromStartYear,
  type ViewMode,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { bankStatementImportService } from '../../../services/kt/bankStatementImportService';
import type {
  BankStatementImportReportCompanyCost,
  BankStatementImportReportLine,
} from '../../../services/kt/bankStatementImportModels';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatDateTimeLocal, formatMoney } from '../../../utils/formatters';
import { extractBankTxnCode, importSaoKeFocusPath } from '../../../utils/extractBankTxnCode';
import { openSourceDocumentView } from '../../../utils/openSourceDocumentView';
import { openWorkspaceTab } from '../../../utils/openWorkspaceTab';
import { titleFromPath } from '../../../workspace/workspaceTabTypes';
import {
  DEFAULT_PAGE_SIZE,
  VoucherListPagination,
  type ListPageSize,
} from '../../../components/list/VoucherListPagination';
import {
  createCompanyCodeSearchConfig,
  createCostCodeSearchConfig,
  type CompanyCodeLookupItem,
  type CostCodeLookupItem,
} from '../ImportSaoKePage/components/StepClassifyImp/createClassifyLookupConfigs';
import erp from '../../../styles/erpPage.module.css';
import styles from './BaoCaoImportSaoKePage.module.css';
import {
  BaoCaoImportSaoKeUnitDetailSlideout,
  type UnitDetailTarget,
} from './BaoCaoImportSaoKeUnitDetailSlideout';

const TEST_ID = 'erp-bao-cao-import-sao-ke';
const PAGE_ID = 'kt-bao-cao-import-sao-ke';

const BaoCaoImportSaoKePage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const startYear = import.meta.env.VITE_START_YEAR ? Number(import.meta.env.VITE_START_YEAR) : undefined;
  const yearOpts = startYear ? yearOptionsFromStartYear(startYear) : undefined;

  const [viewMode, setViewMode] = useState<ViewMode>('month');
  const [month, setMonth] = useState(nowMonth());
  const [year, setYear] = useState(nowYear());
  const [quarter, setQuarter] = useState(nowQuarter());
  const [fromDate, setFromDate] = useState<string | undefined>();
  const [toDate, setToDate] = useState<string | undefined>();
  const [companyCode, setCompanyCode] = useState('');
  const [companyDisplay, setCompanyDisplay] = useState('');
  const [costCode, setCostCode] = useState('');
  const [costDisplay, setCostDisplay] = useState('');
  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<ListPageSize>(DEFAULT_PAGE_SIZE);
  const [items, setItems] = useState<BankStatementImportReportLine[]>([]);
  const [byCompanyCost, setByCompanyCost] = useState<BankStatementImportReportCompanyCost[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [totalDebit, setTotalDebit] = useState(0);
  const [totalCredit, setTotalCredit] = useState(0);
  const [importVoucherCount, setImportVoucherCount] = useState(0);
  const [tab, setTab] = useState<'detail' | 'byUnit'>('detail');
  const [unitDetail, setUnitDetail] = useState<UnitDetailTarget | null>(null);

  const { filterLoading, pageLoading, setLoadingMode, beginFetch, endFetch } =
    useServerPagedListLoading();

  const applyPeriodDates = useCallback((mode: ViewMode, m: string, y: string, q: string) => {
    const dates = computeReportPeriodDates(mode, m, y, q);
    setFromDate(dates.fromDate);
    setToDate(dates.toDate);
  }, []);

  useEffect(() => {
    applyPeriodDates('month', nowMonth(), nowYear(), nowQuarter());
  }, [applyPeriodDates]);

  const fetchReport = useCallback(
    async (targetPage: number, mode: 'load' | 'page' = 'load', searchTerm = search) => {
      setLoadingMode(mode === 'load' ? 'filter' : 'page');
      beginFetch();
      try {
        const data = await bankStatementImportService.getImportReport({
          fromDate,
          toDate,
          companyCode: companyCode.trim() || undefined,
          costCode: costCode.trim() || undefined,
          search: searchTerm.trim() || undefined,
          page: targetPage,
          pageSize,
        });
        setItems(data.items ?? []);
        setByCompanyCost(data.byCompanyCost ?? []);
        setTotalCount(data.totalCount ?? 0);
        setPage(data.page ?? targetPage);
        setTotalDebit(data.totalDebit ?? 0);
        setTotalCredit(data.totalCredit ?? 0);
        setImportVoucherCount(data.importVoucherCount ?? 0);
      } catch (err) {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được báo cáo phiếu import'),
          type: 'error',
        });
      } finally {
        endFetch();
      }
    },
    [
      beginFetch,
      companyCode,
      costCode,
      search,
      dispatch,
      endFetch,
      fromDate,
      pageSize,
      setLoadingMode,
      toDate,
    ],
  );

  const didAutoFetch = useRef(false);
  useEffect(() => {
    if (didAutoFetch.current || !fromDate || !toDate) return;
    didAutoFetch.current = true;
    void fetchReport(1, 'load');
  }, [fetchReport, fromDate, toDate]);

  const handleView = useCallback(() => {
    const nextSearch = searchDraft.trim();
    setSearch(nextSearch);
    setPage(1);
    void fetchReport(1, 'load', nextSearch);
  }, [fetchReport, searchDraft]);

  const handlePeriodModeChange = (mode: ViewMode) => {
    setViewMode(mode);
    applyPeriodDates(mode, month, year, quarter);
  };

  const handleMonthChange = (m: string) => {
    setMonth(m);
    applyPeriodDates(viewMode, m, year, quarter);
  };

  const handleYearChange = (y: string) => {
    setYear(y);
    applyPeriodDates(viewMode, month, y, quarter);
  };

  const handleQuarterChange = (q: string) => {
    setQuarter(q);
    applyPeriodDates(viewMode, month, year, q);
  };

  const companyCodeSearchConfig = useMemo(() => createCompanyCodeSearchConfig(), []);
  const costCodeSearchConfig = useMemo(() => createCostCodeSearchConfig(), []);

  const filters = (
    <LinErpListFilterBar
      testIdPrefix={TEST_ID}
      fromDate={fromDate}
      toDate={toDate}
      onDateChange={(from, to) => {
        setFromDate(from);
        setToDate(to);
        setViewMode('day');
      }}
      dateLabel="Thời gian chứng từ"
      expandDateRangeAriaLabel="Thêm đến ngày chứng từ"
      onSearch={handleView}
      searchAriaLabel="Xem báo cáo"
      loading={filterLoading}
      leading={(
        <>
          <div
            className={erp.searchInGrid}
            data-testid={`${TEST_ID}-company-code`}
          >
            <SearchInput
              config={companyCodeSearchConfig}
              label="Đơn vị"
              value={companyCode}
              primaryDisplay={companyDisplay || companyCode}
              onChange={(c: CompanyCodeLookupItem) => {
                setCompanyCode(c.code);
                setCompanyDisplay(c.code);
              }}
              onClear={() => {
                setCompanyCode('');
                setCompanyDisplay('');
              }}
              showSecondaryInput={false}
              placeholder="Chọn đơn vị"
            />
          </div>
          <div
            className={erp.searchInGrid}
            data-testid={`${TEST_ID}-cost-code`}
          >
            <SearchInput
              config={costCodeSearchConfig}
              label="Mã chi phí"
              value={costCode}
              primaryDisplay={costDisplay || costCode}
              onChange={(c: CostCodeLookupItem) => {
                setCostCode(c.code);
                const name = (c.name || '').trim();
                setCostDisplay(name ? `${c.code} — ${name}` : c.code);
              }}
              onClear={() => {
                setCostCode('');
                setCostDisplay('');
              }}
              showSecondaryInput={false}
              placeholder="Chọn mã chi phí"
            />
          </div>
          <div data-testid={`${TEST_ID}-search`}>
            <SearchTextInput
              label="Tìm"
              value={searchDraft}
              onChange={setSearchDraft}
              placeholder="Mã GD, diễn giải, số/tiêu đề IMP…"
              testId={`${TEST_ID}-filter-search`}
            />
          </div>
        </>
      )}
      dateLeading={(
        <LinReportPeriodSelectorFields
          testIdPrefix={TEST_ID}
          labels={{
            viewMode: 'Xem theo',
            fieldMonth: 'Tháng',
            fieldYear: 'Năm',
            fieldQuarter: 'Quý',
          }}
          viewMode={viewMode}
          month={month}
          year={year}
          quarter={quarter}
          yearOptions={yearOpts}
          onViewModeChange={handlePeriodModeChange}
          onMonthChange={handleMonthChange}
          onYearChange={handleYearChange}
          onQuarterChange={handleQuarterChange}
        />
      )}
    />
  );

  const openCreatedVoucher = useCallback(
    (row: BankStatementImportReportLine) => {
      const viewUrl = (row.createdVoucherViewUrl || '').trim();
      const code = (row.createdVoucherCode || '').trim();
      if (!viewUrl) {
        dispatchAppToast(dispatch, {
          type: 'info',
          message: code
            ? `CT «${code}» chưa có link mở — kiểm tra lại sau khi tạo từ IMP`
            : 'Dòng này chưa tạo chứng từ gốc (BC/BN/UNC/CTNB)',
        });
        return;
      }
      const label = titleFromPath(viewUrl);
      openSourceDocumentView({
        sourceDocumentViewUrl: viewUrl,
        title: code ? `${label} — ${code}` : `${label}…`,
        returnPath: `${location.pathname}${location.search}`,
        returnTitle: 'Báo cáo phiếu import sao kê',
        documentType: row.createdVoucherKind ?? undefined,
        navigate,
      });
    },
    [dispatch, location.pathname, location.search, navigate],
  );

  const openImportAtTxn = useCallback(
    (row: BankStatementImportReportLine, e: React.MouseEvent) => {
      if (e.metaKey || e.ctrlKey || e.shiftKey || e.button === 1) return;
      e.preventDefault();
      const gd = (row.referenceCode || extractBankTxnCode(row.description, row.referenceCode) || '').trim();
      if (!gd || !row.importId) return;
      openWorkspaceTab({
        path: importSaoKeFocusPath(row.importId, gd),
        title: row.importCode ? `${row.importCode} · ${gd}` : gd,
        returnPath: `${location.pathname}${location.search}`,
        returnTitle: 'Báo cáo phiếu import sao kê',
      }, navigate);
    },
    [location.pathname, location.search, navigate],
  );

  const summaryHelp = useMemo(
    () =>
      `${importVoucherCount} phiếu · ${totalCount} dòng · Chi ${formatMoney(totalDebit)} · Thu ${formatMoney(totalCredit)}`,
    [importVoucherCount, totalCount, totalCredit, totalDebit],
  );

  const detailTable = (
    <div className={`${erp.tableWrapper} ${styles.tableWrap}`} data-testid={`${TEST_ID}-detail-grid`}>
      <table className={erp.table}>
        <thead>
          <tr>
            <th>STT</th>
            <th>Ngày chứng từ</th>
            <th>Số IMP</th>
            <th>Tiêu đề</th>
            <th>Mã GD</th>
            <th>CT gốc</th>
            <th>Người import</th>
            <th>Đơn vị (dòng)</th>
            <th>Mã CP</th>
            <th>Định khoản</th>
            <th>Thời gian import</th>
            <th className={`${erp.colAmount} ${styles.num}`}>Chi</th>
            <th className={`${erp.colAmount} ${styles.num}`}>Thu</th>
            <th>Đối tượng</th>
            <th className={styles.descLong}>Diễn giải</th>
            <th>Nguồn sao kê</th>
          </tr>
        </thead>
        <tbody>
          {items.length === 0 ? (
            <tr>
              <td colSpan={16} className={styles.emptyCell}>
                {filterLoading || pageLoading
                  ? 'Đang tải…'
                  : 'Không có dòng khớp bộ lọc — bỏ Đơn vị/Mã CP hoặc đổi kỳ, rồi bấm Xem.'}
              </td>
            </tr>
          ) : (
            items.map((row, idx) => {
              const gd = (row.referenceCode || extractBankTxnCode(row.description, row.referenceCode) || '').trim();
              return (
              <tr key={row.lineId}>
                <td>{(page - 1) * pageSize + idx + 1}</td>
                <td>{row.transactionDate || '—'}</td>
                <td>
                  <a href={`/kt/import-sao-ke/${row.importId}`} data-testid={`${TEST_ID}-link-${row.importCode}`}>
                    {row.importCode}
                  </a>
                </td>
                <td className={styles.desc} title={row.importTitle || undefined}>
                  {row.importTitle || '—'}
                </td>
                <td className={styles.txnCode}>
                  {gd ? (
                    <a
                      href={importSaoKeFocusPath(row.importId, gd)}
                      className={styles.linkBtn}
                      data-testid={`${TEST_ID}-gd-${row.lineId}`}
                      title="Mở phiếu import tại giao dịch này"
                      onClick={e => openImportAtTxn(row, e)}
                    >
                      {gd}
                    </a>
                  ) : '—'}
                </td>
                <td>
                  {row.createdVoucherCode && row.createdVoucherViewUrl ? (
                    <button
                      type="button"
                      className={styles.linkBtn}
                      data-testid={`${TEST_ID}-src-voucher-${row.lineId}`}
                      title="Mở chứng từ gốc để đối soát"
                      onClick={() => openCreatedVoucher(row)}
                    >
                      {row.createdVoucherCode}
                    </button>
                  ) : (
                    <span className={styles.muted} title={row.suggestedVoucherType || undefined}>
                      —
                    </span>
                  )}
                </td>
                <td>{row.importedByName || row.importedByEmployeeCode || '—'}</td>
                <td>{row.companyCode || '—'}</td>
                <td>{row.costCode || '—'}</td>
                <td>{row.postingReasonCode || '—'}</td>
                <td>{formatDateTimeLocal(row.importedAt)}</td>
                <td className={`${erp.colAmount} ${styles.num}`}>{formatMoney(row.debitAmount)}</td>
                <td className={`${erp.colAmount} ${styles.num}`}>{formatMoney(row.creditAmount)}</td>
                <td>{row.customerCode || row.customerName || '—'}</td>
                <td className={styles.descLong} title={row.description || undefined}>
                  {row.description || '—'}
                </td>
                <td className={styles.ref} title={row.importReference || undefined}>
                  {row.importReference || '—'}
                </td>
              </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );

  const unitGroups = useMemo(() => {
    const map = new Map<string, BankStatementImportReportCompanyCost[]>();
    for (const row of byCompanyCost) {
      const key = (row.companyCode || '').trim() || '(trống)';
      const list = map.get(key);
      if (list) list.push(row);
      else map.set(key, [row]);
    }
    const groups = [...map.entries()].map(([companyCode, rows]) => {
      let lineCount = 0;
      let debit = 0;
      let credit = 0;
      let amount = 0;
      for (const r of rows) {
        lineCount += r.lineCount ?? 0;
        debit += r.totalDebit ?? 0;
        credit += r.totalCredit ?? 0;
        amount += r.totalAmount ?? 0;
      }
      return { companyCode, rows, lineCount, debit, credit, amount };
    });
    let lineCount = 0;
    let debit = 0;
    let credit = 0;
    let amount = 0;
    for (const g of groups) {
      lineCount += g.lineCount;
      debit += g.debit;
      credit += g.credit;
      amount += g.amount;
    }
    return { groups, grand: { lineCount, debit, credit, amount } };
  }, [byCompanyCost]);

  const unitTable = (
    <div className={`${erp.tableWrapper} ${styles.tableWrap}`} data-testid={`${TEST_ID}-unit-grid`}>
      <table className={erp.table}>
        <thead>
          <tr>
            <th className={styles.colAction} aria-label="Thao tác" />
            <th>STT</th>
            <th>Đơn vị cơ sở</th>
            <th>Mã chi phí</th>
            <th>Số dòng</th>
            <th className={`${erp.colAmount} ${styles.num}`}>Tổng chi</th>
            <th className={`${erp.colAmount} ${styles.num}`}>Tổng thu</th>
            <th className={`${erp.colAmount} ${styles.num}`}>Tổng tiền</th>
          </tr>
        </thead>
        <tbody>
          {unitGroups.groups.length === 0 ? (
            <tr>
              <td colSpan={8} className={styles.emptyCell}>
                {filterLoading || pageLoading
                  ? 'Đang tải…'
                  : 'Chưa có tổng hợp đơn vị × mã CP cho bộ lọc hiện tại.'}
              </td>
            </tr>
          ) : (
            <>
              {(() => {
                let stt = 0;
                return unitGroups.groups.flatMap((group) => {
                  const detailRows = group.rows.map((row, idx) => {
                    stt += 1;
                    const rowCompany = (row.companyCode || '').trim();
                    const rowCost = (row.costCode || '').trim();
                    return (
                      <tr key={`${group.companyCode}|${row.costCode}|${idx}`}>
                        <td className={styles.colAction}>
                          <button
                            type="button"
                            className={styles.viewBtn}
                            title="Xem chi tiết dòng chứng từ"
                            aria-label="Xem chi tiết dòng chứng từ"
                            data-testid={`${TEST_ID}-unit-view-${rowCompany || 'empty'}-${rowCost || 'empty'}`}
                            onClick={() =>
                              setUnitDetail({
                                companyCode: rowCompany,
                                costCode: rowCost,
                                lineCount: row.lineCount,
                                totalDebit: row.totalDebit,
                                totalCredit: row.totalCredit,
                                totalAmount: row.totalAmount,
                              })
                            }
                          >
                            <i className="fas fa-eye" aria-hidden />
                          </button>
                        </td>
                        <td>{stt}</td>
                        <td>{rowCompany || '(trống)'}</td>
                        <td>{rowCost || '(trống)'}</td>
                        <td>{row.lineCount}</td>
                        <td className={`${erp.colAmount} ${styles.num}`}>{formatMoney(row.totalDebit)}</td>
                        <td className={`${erp.colAmount} ${styles.num}`}>{formatMoney(row.totalCredit)}</td>
                        <td className={`${erp.colAmount} ${styles.num}`}>{formatMoney(row.totalAmount)}</td>
                      </tr>
                    );
                  });
                  const subtotal = (
                    <tr
                      key={`subtotal-${group.companyCode}`}
                      className={styles.companyTotalRow}
                      data-testid={`${TEST_ID}-company-total-${group.companyCode}`}
                    >
                      <td />
                      <td colSpan={2}>Tổng {group.companyCode}</td>
                      <td />
                      <td>{group.lineCount}</td>
                      <td className={`${erp.colAmount} ${styles.num} ${styles.amtDebit}`}>
                        {formatMoney(group.debit)}
                      </td>
                      <td className={`${erp.colAmount} ${styles.num} ${styles.amtCredit}`}>
                        {formatMoney(group.credit)}
                      </td>
                      <td className={`${erp.colAmount} ${styles.num} ${styles.amtTotal}`}>
                        {formatMoney(group.amount)}
                      </td>
                    </tr>
                  );
                  return [...detailRows, subtotal];
                });
              })()}
              <tr className={styles.totalRow} data-testid={`${TEST_ID}-unit-total`}>
                <td />
                <td colSpan={3}>Tổng cộng</td>
                <td>{unitGroups.grand.lineCount}</td>
                <td className={`${erp.colAmount} ${styles.num} ${styles.amtDebit}`}>
                  {formatMoney(unitGroups.grand.debit)}
                </td>
                <td className={`${erp.colAmount} ${styles.num} ${styles.amtCredit}`}>
                  {formatMoney(unitGroups.grand.credit)}
                </td>
                <td className={`${erp.colAmount} ${styles.num} ${styles.amtTotal}`}>
                  {formatMoney(unitGroups.grand.amount)}
                </td>
              </tr>
            </>
          )}
        </tbody>
      </table>
    </div>
  );

  return (
    <div
      className={erp.voucherListRoot}
      data-voucher-list-page
      data-catalog-list-page
      data-report-list-page
      data-lin-list-layout="erp-filter-bar"
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${styles.reportPage}`}
        listLayoutVariant="erp-filter-bar"
        listHeaderClassName={LIN_ERP_LIST_FILTER_LAYOUT.header}
        listFiltersClassName={LIN_ERP_LIST_FILTER_LAYOUT.filtersHost}
        header={{
          title: 'Báo cáo phiếu import sao kê',
          titleIconClass: 'fas fa-file-import',
          pageId: PAGE_ID,
        }}
        listTitle="Danh sách phiếu import sao kê"
        listTitleHelp={summaryHelp}
        filters={filters}
        filterBarLayout="standard"
        showTableLoading={filterLoading || pageLoading}
        pageLoading={pageLoading}
        skeletonRows={8}
        footer={
          tab === 'detail' && totalCount > 0 ? (
            <VoucherListPagination
              testIdPrefix={TEST_ID}
              page={page}
              totalCount={totalCount}
              pageSize={pageSize}
              onPageChange={(p) => {
                setPage(p);
                void fetchReport(p, 'page');
              }}
              onPageSizeChange={(ps) => {
                setPageSize(ps as ListPageSize);
                setPage(1);
                void fetchReport(1, 'load');
              }}
            />
          ) : undefined
        }
      >
        <div className={styles.bodyStack}>
          <div className={styles.tabs} data-testid={`${TEST_ID}-tabs`}>
            <button
              type="button"
              className={tab === 'detail' ? styles.tabActive : styles.tab}
              onClick={() => setTab('detail')}
              data-testid={`${TEST_ID}-tab-detail`}
            >
              Chi tiết import
            </button>
            <button
              type="button"
              className={tab === 'byUnit' ? styles.tabActive : styles.tab}
              onClick={() => setTab('byUnit')}
              data-testid={`${TEST_ID}-tab-by-unit`}
            >
              Theo đơn vị × mã CP
            </button>
          </div>
          {tab === 'detail' ? detailTable : unitTable}
        </div>
      </LinPageLayout>
      <BaoCaoImportSaoKeUnitDetailSlideout
        isOpen={unitDetail != null}
        onClose={() => setUnitDetail(null)}
        target={unitDetail}
        fromDate={fromDate}
        toDate={toDate}
        search={search}
        testIdPrefix={TEST_ID}
      />
    </div>
  );
};

export default BaoCaoImportSaoKePage;
